<template><v-row justify="center" class="auth-layout"><v-col cols="12" sm="8" md="5"><v-card class="auth-card pa-7"><h1 class="text-h4 font-weight-bold mb-3">Recuperar acceso</h1><p class="text-medium-emphasis mb-6">Indica tu usuario. Un administrador del taller gestionará la recuperación de forma segura.</p><AppAlert :message="message" :type="type" @clear="message=''"/><v-form v-model="valid" @submit.prevent="submit"><v-text-field v-model.trim="username" label="Usuario" prepend-inner-icon="mdi-account-outline" :rules="[v=>v?.length>=3||'Usuario inválido']"/><v-btn block size="large" color="primary" type="submit" :disabled="!valid" :loading="loading">Solicitar recuperación</v-btn></v-form></v-card></v-col></v-row></template>
<script setup>import{ref}from'vue';import api from'../services/api';import AppAlert from'../components/AppAlert.vue';const username=ref(''),valid=ref(false),loading=ref(false),message=ref(''),type=ref('success');async function submit(){loading.value=true;try{message.value=(await api.post('/auth/forgot-password',{username:username.value})).data.message;type.value='success'}catch(e){message.value=e.response?.data?.detail||'No fue posible procesar la solicitud';type.value='error'}finally{loading.value=false}}</script>
